import os
import boto3
from botocore.exceptions import ClientError


def analyze_and_redact_text(text: str, threshold: float = 0.5) -> dict:
    access_key = os.environ.get("AWS_ACCESS_KEY_ID")
    secret_key = os.environ.get("AWS_SECRET_ACCESS_KEY")
    region = os.environ.get("AWS_DEFAULT_REGION", "us-east-1")

    if not access_key or not secret_key:
        raise ValueError("AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY environment variables are required.")

    client = boto3.client(
        "comprehend",
        aws_access_key_id=access_key,
        aws_secret_access_key=secret_key,
        region_name=region
    )

    try:
        response = client.detect_toxic_content(Text=text)
    except ClientError as e:
        raise RuntimeError(f"Amazon Comprehend API error: {e}") from e

    toxic_labels = response.get("Labels", [])
    flagged_spans = []

    for label in toxic_labels:
        for span in label.get("Spans", []):
            if span["Score"] >= threshold:
                flagged_spans.append({
                    "category": label["Name"],
                    "begin_offset": span["BeginOffset"],
                    "end_offset": span["EndOffset"],
                    "confidence": span["Score"]
                })

    flagged_spans.sort(key=lambda x: x["begin_offset"], reverse=True)
    redacted = text
    for span in flagged_spans:
        redacted = redacted[:span["begin_offset"]] + "[REDACTED]" + redacted[span["end_offset"]:]

    return {
        "is_unsafe": len(flagged_spans) > 0,
        "flags": sorted(list(set(s["category"] for s in flagged_spans))),
        "spans": flagged_spans,
        "redacted_text": redacted,
        "original_text": text
    }
